# Shared helpers for the Android dependency recipes (brief S1).
# Sourced by deps/build-sysroot.sh and tools/build-engine-android.sh.
#
# Environment it expects (with defaults):
#   ANDROID_NDK_HOME  NDK root (must be the version pinned in deps/config.sh)
#   DTA_WORK          scratch dir for sources and build trees
#   DTA_DL            download cache

DTA_DEPS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=../config.sh
. "$DTA_DEPS_DIR/config.sh"

: "${DTA_WORK:=$PWD/_dta-work}"
: "${DTA_DL:=$DTA_WORK/downloads}"
: "${DTA_JOBS:=$(nproc)}"

dta_log() { printf '[dta %s] %s\n' "$(date -u +%H:%M:%S)" "$*" >&2; }
dta_die() { dta_log "ERROR: $*"; exit 1; }

# dta_setup_env <abi>: compiler, flags, pkg-config and cross files for one ABI.
dta_setup_env() {
  DTA_ABI="$1"
  case "$DTA_ABI" in
    arm64-v8a) DTA_TRIPLE=aarch64-linux-android; DTA_CPU_FAMILY=aarch64; DTA_CPU=armv8-a; DTA_RUST_TARGET=aarch64-linux-android; DTA_LLVM_ARCH=aarch64 ;;
    x86_64)    DTA_TRIPLE=x86_64-linux-android;  DTA_CPU_FAMILY=x86_64;  DTA_CPU=x86_64;  DTA_RUST_TARGET=x86_64-linux-android;  DTA_LLVM_ARCH=x86_64 ;;
    *) dta_die "unknown ABI '$DTA_ABI' (use arm64-v8a or x86_64)" ;;
  esac
  [ -n "${ANDROID_NDK_HOME:-}" ] && [ -d "$ANDROID_NDK_HOME" ] || dta_die "ANDROID_NDK_HOME not set or missing"
  local ndkver
  ndkver=$(sed -n 's/^Pkg.Revision *= *//p' "$ANDROID_NDK_HOME/source.properties")
  [ "$ndkver" = "$DTA_NDK_VERSION" ] || dta_die "NDK is $ndkver, deps/config.sh pins $DTA_NDK_VERSION"

  DTA_PREFIX="$DTA_PREFIX_BASE/sysroot-$DTA_ABI"
  DTA_TOOLCHAIN="$ANDROID_NDK_HOME/toolchains/llvm/prebuilt/linux-x86_64"
  DTA_NDK_SYSROOT="$DTA_TOOLCHAIN/sysroot"
  DTA_CMAKE_TOOLCHAIN="$ANDROID_NDK_HOME/build/cmake/android.toolchain.cmake"
  local tc="$DTA_TOOLCHAIN/bin"

  export CC="$tc/${DTA_TRIPLE}${DTA_API}-clang"
  export CXX="$tc/${DTA_TRIPLE}${DTA_API}-clang++"
  export AR="$tc/llvm-ar" RANLIB="$tc/llvm-ranlib" STRIP="$tc/llvm-strip"
  export NM="$tc/llvm-nm" OBJCOPY="$tc/llvm-objcopy" READELF="$tc/llvm-readelf" LD="$tc/ld.lld"
  # 16 KB page alignment (Android 15+ devices); NDK r28+ defaults to it, we
  # also say it explicitly so every recipe gets it.
  DTA_PAGE_LDFLAGS="-Wl,-z,max-page-size=16384 -Wl,-z,common-page-size=16384"
  export CPPFLAGS="-I$DTA_PREFIX/include"
  export CFLAGS="-O2 -fPIC -g0"
  export CXXFLAGS="-O2 -fPIC -g0"
  export LDFLAGS="-L$DTA_PREFIX/lib -Wl,-rpath-link=$DTA_PREFIX/lib $DTA_PAGE_LDFLAGS"
  # libintl: bionic has no gettext. proxy-libintl provides libintl.so whose
  # header maps gettext() & co. to g_libintl_*; link it where used.
  if [ -e "$DTA_PREFIX/lib/libintl.so" ]; then
    LDFLAGS="$LDFLAGS -Wl,--push-state,--as-needed -lintl -Wl,--pop-state"
  fi
  export PKG_CONFIG=pkg-config
  export PKG_CONFIG_LIBDIR="$DTA_PREFIX/lib/pkgconfig:$DTA_PREFIX/share/pkgconfig"
  unset PKG_CONFIG_PATH PKG_CONFIG_SYSROOT_DIR
  # Rust (librsvg): linker and C compiler per target
  local rt_upper
  rt_upper=$(echo "$DTA_RUST_TARGET" | tr 'a-z-' 'A-Z_')
  export "CARGO_TARGET_${rt_upper}_LINKER=$CC"
  export "CC_${DTA_RUST_TARGET//-/_}=$CC" "CXX_${DTA_RUST_TARGET//-/_}=$CXX" "AR_${DTA_RUST_TARGET//-/_}=$AR"

  mkdir -p "$DTA_WORK" "$DTA_DL"
  DTA_MESON_CROSS="$DTA_WORK/meson-cross-$DTA_ABI.ini"
  dta_write_meson_cross > "$DTA_MESON_CROSS"
}

_dta_meson_list() { # space separated words -> meson array
  local out="" w
  for w in "$@"; do out="$out'$w', "; done
  printf '[%s]' "${out%, }"
}

dta_write_meson_cross() {
  # shellcheck disable=SC2086
  cat <<EOF
# generated by deps/lib/common.sh for $DTA_ABI, API $DTA_API
[binaries]
c = '$CC'
cpp = '$CXX'
ar = '$AR'
strip = '$STRIP'
nm = '$NM'
objcopy = '$OBJCOPY'
ld = '$LD'
pkg-config = 'pkg-config'

[built-in options]
c_args = $(_dta_meson_list $CPPFLAGS $CFLAGS)
cpp_args = $(_dta_meson_list $CPPFLAGS $CXXFLAGS)
c_link_args = $(_dta_meson_list $LDFLAGS)
cpp_link_args = $(_dta_meson_list $LDFLAGS)

[properties]
pkg_config_libdir = '$PKG_CONFIG_LIBDIR'
needs_exe_wrapper = true
# answers for run-checks that cannot run when cross compiling (glib, cairo)
have_c99_vsnprintf = true
have_c99_snprintf = true
have_unix98_printf = true
ipc_rmid_deferred_release = false

[host_machine]
system = 'android'
subsystem = 'android'
kernel = 'linux'
cpu_family = '$DTA_CPU_FAMILY'
cpu = '$DTA_CPU'
endian = 'little'
EOF
}

# ---- source handling -------------------------------------------------------

# dta_fetch: download $URL into $DTA_DL and check $SHA256, or clone
# $GIT_URL at $GIT_COMMIT. Leaves the source tree in $SRC.
dta_fetch() {
  local wd="$DTA_WORK/src/$DTA_ABI"
  mkdir -p "$wd"
  rm -rf "$wd/$NAME"
  if [ -z "${GIT_URL:-}" ] && [ -z "${URL:-}" ]; then
    mkdir -p "$wd/$NAME"; SRC="$wd/$NAME"; return 0
  elif [ -n "${GIT_URL:-}" ]; then
    local cache="$DTA_DL/$NAME-$GIT_COMMIT.git"
    if [ ! -d "$cache" ]; then
      git init -q --bare "$cache"
      git -C "$cache" fetch -q --depth 1 "$GIT_URL" "$GIT_COMMIT" || dta_die "git fetch $GIT_URL $GIT_COMMIT failed"
    fi
    git -C "$cache" rev-parse --verify -q "$GIT_COMMIT^{commit}" >/dev/null || dta_die "commit $GIT_COMMIT missing"
    mkdir -p "$wd/$NAME"
    git -C "$cache" archive "$GIT_COMMIT" | tar -x -C "$wd/$NAME"
    SRC="$wd/$NAME"
  else
    local file="${FILE:-$(basename "$URL")}"
    local dl="$DTA_DL/$NAME-$VERSION-$file"
    if [ ! -s "$dl" ] || ! echo "$SHA256  $dl" | sha256sum -c --status; then
      dta_log "downloading $URL"
      curl -fsSL --retry 4 --retry-delay 5 -o "$dl.part" "$URL" || dta_die "download failed: $URL"
      mv "$dl.part" "$dl"
    fi
    local got
    got=$(sha256sum "$dl" | cut -d' ' -f1)
    if [ "$got" != "$SHA256" ]; then
      dta_die "sha256 mismatch for $URL: expected $SHA256, got $got"
    fi
    mkdir -p "$wd/$NAME.x"
    case "$dl" in
      *.zip) (cd "$wd/$NAME.x" && unzip -q "$dl") ;;
      *) tar -xf "$dl" -C "$wd/$NAME.x" ;;
    esac
    local top
    top=$(find "$wd/$NAME.x" -mindepth 1 -maxdepth 1)
    if [ "$(echo "$top" | wc -l)" = 1 ] && [ -d "$top" ]; then mv "$top" "$wd/$NAME"; rmdir "$wd/$NAME.x"
    else mv "$wd/$NAME.x" "$wd/$NAME"; fi
    SRC="$wd/$NAME"
  fi
  local p
  for p in "$DTA_DEPS_DIR/recipes/$NAME"/*.patch; do
    [ -e "$p" ] || continue
    dta_log "applying $(basename "$p")"
    patch -d "$SRC" -p1 --forward --batch < "$p" || dta_die "patch $(basename "$p") failed"
  done
}

# ---- build system helpers (install into $STAGE via DESTDIR) ---------------

dta_meson() {
  local b="$SRC/_build-$DTA_ABI"
  meson setup "$b" "$SRC" --cross-file "$DTA_MESON_CROSS" \
    --prefix "$DTA_PREFIX" --libdir lib --buildtype release \
    --default-library shared --wrap-mode nodownload \
    -Db_pie=true "$@" || return 1
  # -k 0: report every failing target, not only the first
  ninja -C "$b" -j "$DTA_JOBS" -k 0 || return 1
  DESTDIR="$STAGE" meson install -C "$b" --no-rebuild || return 1
}

dta_cmake_args() {
  echo "-DCMAKE_TOOLCHAIN_FILE=$DTA_CMAKE_TOOLCHAIN"
  echo "-DANDROID_ABI=$DTA_ABI"
  echo "-DANDROID_PLATFORM=android-$DTA_API"
  echo "-DANDROID_STL=c++_shared"
  echo "-DCMAKE_BUILD_TYPE=Release"
  echo "-DCMAKE_INSTALL_PREFIX=$DTA_PREFIX"
  echo "-DCMAKE_INSTALL_LIBDIR=lib"
  echo "-DCMAKE_PREFIX_PATH=$DTA_PREFIX"
  echo "-DCMAKE_FIND_ROOT_PATH=$DTA_PREFIX"
  echo "-DCMAKE_C_FLAGS=$CPPFLAGS $CFLAGS"
  echo "-DCMAKE_CXX_FLAGS=$CPPFLAGS $CXXFLAGS"
  echo "-DCMAKE_SHARED_LINKER_FLAGS=$LDFLAGS"
  echo "-DCMAKE_MODULE_LINKER_FLAGS=$LDFLAGS"
  echo "-DCMAKE_EXE_LINKER_FLAGS=$LDFLAGS"
  echo "-DCMAKE_POLICY_VERSION_MINIMUM=3.5"
  echo "-DBUILD_SHARED_LIBS=ON"
}

dta_cmake() {
  local b="$SRC/_build-$DTA_ABI"
  local args=()
  mapfile -t args < <(dta_cmake_args)
  cmake -S "${CMAKE_SRC:-$SRC}" -B "$b" -G Ninja "${args[@]}" "$@" || return 1
  cmake --build "$b" -j "$DTA_JOBS" -- -k 0 || return 1
  DESTDIR="$STAGE" cmake --install "$b" || return 1
}

dta_autotools() {
  local b="$SRC/_build-$DTA_ABI"
  mkdir -p "$b"
  (cd "$b" && "${CONFIGURE:-$SRC/configure}" --host="$DTA_TRIPLE" --prefix="$DTA_PREFIX" \
      --libdir="$DTA_PREFIX/lib" --enable-shared --disable-static "$@") || return 1
  make -C "$b" -j "$DTA_JOBS" || return 1
  make -C "$b" install DESTDIR="$STAGE" || return 1
}

# ---- post-processing of one package ---------------------------------------

# Remove build-only clutter and make pkg-config files relocatable.
dta_tidy_stage() {
  local root="$STAGE$DTA_PREFIX"
  [ -d "$root" ] || return 0
  find "$root" -name '*.la' -delete
  rm -rf "$root/share/man" "$root/share/doc" "$root/share/gtk-doc" "$root/share/info" \
         "$root/share/bash-completion" "$root/share/locale"
  local pc
  while IFS= read -r pc; do
    sed -i "s|$DTA_PREFIX|\${pcfiledir}/../..|g" "$pc"
  done < <(find "$root/lib/pkgconfig" "$root/share/pkgconfig" -name '*.pc' 2>/dev/null)
}
